#!/usr/bin/env node
/**
 * Resume-safe production portrait generator.
 * Each asset is generated by the installed proxy-imagegen skill, which calls
 * GPT Image 2 through the active Codex Responses API provider.
 */
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import process from 'node:process';

const projectRoot = path.resolve(import.meta.dirname, '..');
const sourceManifestPath = path.join(projectRoot, 'public/mods/qwen-image-pack/manifest.json');
const outputDirectory = path.join(projectRoot, 'public/mods/gpt-image-2-pack/portraits');
const generator = path.join(os.homedir(), '.codex/skills/proxy-imagegen/scripts/generate.ps1');
const concurrency = Math.max(1, Math.min(6, Number.parseInt(process.env.IT_IMAGE_CONCURRENCY ?? '4', 10) || 4));

if (!fs.existsSync(generator)) throw new Error(`proxy-imagegen generator not found: ${generator}`);
fs.mkdirSync(outputDirectory, { recursive: true });

const sourceManifest = JSON.parse(fs.readFileSync(sourceManifestPath, 'utf8'));
const sourceItems = sourceManifest.items.filter((item) => item.type === 'portrait' && item.charId);
const seen = new Set();
const jobs = sourceItems.flatMap((item) => {
  if (seen.has(item.charId)) return [];
  seen.add(item.charId);
  const fileName = item.output.split('/').at(-1);
  const output = path.join(outputDirectory, fileName);
  if (fs.existsSync(output) && fs.statSync(output).size > 0) return [];

  const character = item.prompt.match(/Character: (.*?)\. Level context:/)?.[1] ?? item.charId;
  const levelContext = item.prompt.match(/Level context: (.*?)\. Mood:/)?.[1] ?? item.levelId;
  const narrative = item.prompt.match(/Mood: (.*?)\. highly detailed/)?.[1] ?? levelContext;
  const prompt = [
    'Production character portrait for the psychological strategy simulation game Intention Tower.',
    `Exactly one character: ${character}.`,
    `Story context: ${levelContext}. Narrative role and mood: ${narrative}.`,
    'Chest-up three-quarter portrait, centered with the full head and shoulders visible, clear distinctive silhouette and emotionally intelligent expression.',
    'Cinematic painterly realism with charcoal-ink texture, grounded anatomy, restrained cyan and amber rim light, subtle cognitive-network filaments in a simple dark atmospheric background.',
    'Square 1:1 composition designed for a game dialogue portrait. No UI frame, no text, no letters, no numbers, no logo, no watermark, no duplicate character, no crowd.',
  ].join(' ');
  return [{ id: item.charId, output, prompt }];
});

function generate(job) {
  return new Promise((resolve, reject) => {
    const child = spawn(generator, ['--prompt', job.prompt, '--out', job.output], {
      cwd: projectRoot,
      stdio: 'inherit',
    });
    child.once('error', reject);
    child.once('exit', (code, signal) => {
      if (code === 0 && fs.existsSync(job.output) && fs.statSync(job.output).size > 0) {
        process.stdout.write(`[portrait] complete ${job.id}\n`);
        resolve();
      } else {
        reject(new Error(`portrait generation failed for ${job.id}: code=${code} signal=${signal}`));
      }
    });
  });
}

let nextJobIndex = 0;
let failed = false;
async function worker() {
  while (!failed) {
    const jobIndex = nextJobIndex;
    nextJobIndex += 1;
    if (jobIndex >= jobs.length) return;
    try {
      await generate(jobs[jobIndex]);
    } catch (error) {
      failed = true;
      throw error;
    }
  }
}

process.stdout.write(`[portrait] pending=${jobs.length} concurrency=${concurrency}\n`);
await Promise.all(Array.from({ length: Math.min(concurrency, jobs.length) }, () => worker()));
process.stdout.write(`[portrait] generated=${jobs.length}\n`);
